<script setup lang="ts">
import { computed,nextTick,onMounted,ref } from 'vue'
import { useRouter } from 'vue-router'
import PlatformLayout from '../components/PlatformLayout.vue'
import AgentRunTrace from '../components/AgentRunTrace.vue'
import { useApi,money,date,type Row } from '../composables/useApi'
const development=import.meta.env.VITE_APP_MODE!=='production'
const {api,act,auth}=useApi(),router=useRouter(),configured=ref(false),session=ref(''),sessions=ref<Row[]>([]),messages=ref<{role:string,content:string}[]>([]),draft=ref<Row|null>(null),text=ref(''),busy=ref(false),confirming=ref(false),error=ref(''),box=ref<HTMLElement>(),runs=ref<Row[]>([])
const overview=ref<Row>({})
const role=computed(()=>auth.user?.role??'OWNER')
const copy=computed(()=>({
 OWNER:{title:'宠物照护助手',detail:'从照顾需求到预约订单，让助手帮你逐步完成。',welcome:'今天，毛孩子需要什么照顾？',placeholder:'告诉我宠物、日期、时间偏好和预算…',tasks:['查看我的宠物和上门地址','帮我预约明天下午的喂养服务，预算50元','重新查询我选择日期的可用时段'],links:[['/pets','宠物档案'],['/book','手动预约']]},
 SITTER:{title:'服务执行助手',detail:'梳理服务安排与照顾要求，把实际履约情况整理成记录。',welcome:'一起安排好每一次上门服务',placeholder:'查询我的日程，或说明某笔订单实际完成的服务…',tasks:['查询我的订单，整理今天的服务安排','查看我的待接单订单和照顾要求','帮我整理服务记录，先查询服务中的订单'],links:[['/sitter','资料与时段'],['/orders','服务订单']]},
 ADMIN:{title:'平台运营助手',detail:'基于真实订单与履约记录，整理待办和投诉处理建议。',welcome:'今天的平台有哪些事情需要处理？',placeholder:'查看运营待办，或指定投诉分析处理依据…',tasks:['查看平台运营概况，整理需要优先处理的待办','查询待审核喂养员，检查资料完整性','查询待处理投诉，帮我分析处理依据'],links:[['/admin','平台管理'],['/complaints','投诉处理']]}
}[role.value]))
const cards=computed(()=>role.value==='ADMIN'?[['待审核喂养员',overview.value.pendingSitters],['待处理投诉',overview.value.openComplaints],['平台订单',overview.value.orders]]:[['待接单',overview.value.pending],['进行中与待确认',overview.value.active],['我的订单',overview.value.orders]])
async function refreshOverview(){overview.value=await api('/agent/overview')}
function suggest(value:string){text.value=value}
async function scroll(){await nextTick();if(box.value)box.value.scrollTop=box.value.scrollHeight}
async function create(){if(busy.value)return;await act(async()=>{const result=await api('/agent/sessions','POST');session.value=result.ID;messages.value=[];draft.value=null;runs.value=[];await list()})}
async function list(){sessions.value=await api<Row[]>('/agent/sessions')}
async function select(id:string){if(busy.value)return;await act(async()=>{const result=await api(`/agent/sessions/${id}`);session.value=id;messages.value=result.HISTORY;draft.value=null;runs.value=await api<Row[]>(`/agent/sessions/${id}/runs`);await scroll()})}
async function send(){if(busy.value||!text.value.trim())return;if(!session.value)await create();if(!session.value)return;busy.value=true;error.value='';const message=text.value;try{const result=await api(`/agent/sessions/${session.value}/messages`,'POST',{message});messages.value.push({role:'USER',content:message},{role:'ASSISTANT',content:result.reply});draft.value=result.draft;text.value='';await list();runs.value=await api<Row[]>(`/agent/sessions/${session.value}/runs`);await scroll()}catch(e){error.value=(e as Error).message;try{runs.value=await api<Row[]>(`/agent/sessions/${session.value}/runs`)}catch{}}finally{busy.value=false}}
async function confirm(){if(!draft.value||confirming.value)return;confirming.value=true;if(draft.value.KIND){if(await act(()=>api(`/agent/action-drafts/${draft.value!.ID}/confirm`,'POST',{content:draft.value!.CONTENT}),'已确认保存')){const target=draft.value.KIND==='RESOLUTION'?'/complaints':'/orders';draft.value=null;await router.push(target)}}else if(await act(()=>api(`/agent/drafts/${draft.value!.ID}/confirm`,'POST'),'预约已创建'))await router.push('/orders');confirming.value=false}
onMounted(async()=>{try{configured.value=(await api('/agent/status')).configured;await refreshOverview();await list();if(sessions.value.length)await select(sessions.value[0]!.ID)}catch(e){error.value=(e as Error).message}})
</script>
<template><PlatformLayout><div class="page-heading"><div><span class="eyebrow">YOUR AI WORKSPACE</span><h1>{{ copy.title }}</h1><p>{{ copy.detail }}</p></div><el-tag>{{ configured?'DeepSeek 已连接配置':'DeepSeek 尚未配置' }}</el-tag></div><el-alert v-if="!configured" :title="development ? '当前尚未配置模型服务。请在后端通过 DEEPSEEK_API_KEY 环境变量设置密钥后重启，也可以先使用普通预约。' : '预约助手暂时不可用，请使用普通预约或联系管理员。'" type="info" :closable="false"/><section class="agent-overview" aria-label="实时业务待办"><article v-for="card in cards" :key="String(card[0])"><span>{{ card[0] }}</span><strong>{{ card[1] ?? '—' }}</strong></article><div class="agent-shortcuts"><RouterLink v-for="link in copy.links" :key="link[0]" :to="link[0]!">{{ link[1] }} ↗</RouterLink></div></section><div class="agent-workflow"><span>01 说明需求</span><span>02 查询真实数据</span><span>03 核实草稿</span><span>04 确认执行</span></div><div class="agent-layout"><aside class="business-card"><el-button @click="create" :disabled="busy">新建对话</el-button><button v-for="s in sessions" :key="s.ID" class="conversation-link" :class="{active:s.ID===session}" :disabled="busy" @click="select(s.ID)">{{ date(s.UPDATED_AT) }}</button></aside><section class="business-card chat-card"><div ref="box" class="chat-history"><div v-if="!messages.length" class="chat-welcome"><span>✣</span><h3>{{ copy.welcome }}</h3><div class="agent-suggestions"><button v-for="task in copy.tasks" :key="task" @click="suggest(task)">{{ task }} <span>↗</span></button></div><p class="muted">请勿在对话中发送门禁密码等敏感信息。</p></div><article v-for="(message,i) in messages" :key="i" class="chat-message" :class="message.role.toLowerCase()"><small>{{ message.role==='USER'?'你':copy.title }}</small><p>{{ message.content }}</p></article><p v-if="busy" class="muted">正在理解需求并查询，请稍候…</p></div><el-alert v-if="error" :title="error" type="error" :closable="false"/><AgentRunTrace v-if="runs.length" :key="runs[0]!.ID" :run-id="runs[0]!.ID"/><article v-if="draft?.KIND" class="draft-card"><h3>{{ draft.KIND==='FULFILLMENT'?'履约记录草稿':'投诉处理建议' }} · 待核实</h3><p>关联编号：{{ draft.TARGET_ID }}</p><el-input v-model="draft.CONTENT" type="textarea" :rows="5" maxlength="1000" show-word-limit/><p class="muted">请核对事实并修改内容。15分钟内确认有效，确认后将{{ draft.KIND==='FULFILLMENT'?'保存履约记录':'保存处理意见并将投诉标记为已处理' }}。</p><el-button type="primary" :loading="confirming" @click="confirm">核实并确认保存</el-button></article><article v-else-if="draft" class="draft-card"><h3>预约草稿 · 等待你确认</h3><p>{{ draft.PET_NAME }} · {{ draft.SITTER_NAME }}</p><p>{{ date(draft.STARTS_AT) }} 至 {{ date(draft.ENDS_AT) }}</p><p>{{ draft.REGION }} {{ draft.DETAIL }}</p><strong>{{ money(draft.PRICE_CENTS) }}</strong><p class="muted">15 分钟内有效，草稿不占用时段。确认时会重新校验。</p><el-button type="primary" :loading="confirming" @click="confirm">确认草稿并创建预约</el-button></article><form class="chat-composer" @submit.prevent="send"><el-input v-model="text" type="textarea" :rows="3" maxlength="2000" :placeholder="copy.placeholder" :disabled="busy||!configured"/><el-button type="primary" native-type="submit" :loading="busy" :disabled="!configured||!text.trim()">发送需求</el-button></form></section></div></PlatformLayout></template>
